SELECT sp.flowregistry, sp.zoneref, sp.memusagegb, sp.flowhrs, sp.proccpu, sp.procgpu, 
       (SELECT SUM(sc.totalpts) FROM scanpointcloud sc WHERE sc.zoneref = sp.zoneref) as totalpts
FROM scanprocessing sp LIMIT 5;

-- Check scans table structure
SELECT column_name FROM information_schema.columns 
WHERE table_name = 'scans' ORDER BY ordinal_position;

-- Check if scans has any relation to flowregistry
SELECT s.questregistry, s.arcref, s.zoneref, s.gbsize 
FROM scans s LIMIT 5;

